contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint deposit, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(deposit > 0);
        require(am > 0);
        require(am <= deposit);
        require(address(this).balance >= deposit);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(
            c.balances(address(this)) == beforeBal - am &&
            address(c).balance == beforeC - am &&
            address(this).balance >= am
        );
    }
    receive() external payable {}
}

