pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 deposit, uint256 am) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit > 0);
        vm.assume(am > 0);
        vm.assume(am <= deposit);
        vm.assume(address(this).balance >= deposit);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeC = address(c).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) == beforeBal - am &&
            address(c).balance == beforeC - am &&
            address(this).balance >= am);
    }

    function testFuzz_run(uint256 deposit, uint256 am) public {
        _run(deposit, am);
    }

    receive() external payable {}
}
